def flatten_deep(nested):
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten_deep(item))
        else:
            result.append(item)
    return result


def path_set(d, path, value):
    keys = path.split(".")
    current = d
    for key in keys[:-1]:
        if key not in current:
            current[key] = {}
        current = current[key]
    current[keys[-1]] = value
    return d


def collect_leaves(tree):
    leaves = []
    if isinstance(tree, dict):
        for v in tree.values():
            leaves.extend(collect_leaves(v))
    elif isinstance(tree, list):
        for item in tree:
            leaves.extend(collect_leaves(item))
    else:
        leaves.append(tree)
    return leaves
